function MazeUI_EdgeRole:__init()
end


function MazeUI_EdgeRole:__delete()
end




function MazeUI_EdgeRole:Start()
    KTool.SetActive(self.controller.gameObject, true)

    assert( self.arrowRTF )
    assert( self.uiSwitchImage )
    assert( self.button )

    self.transform = self.controller.gameObject.transform
    
    self.roleCanvasGroup = KTool.GetComponent(self.controller.gameObject, typeof(CanvasGroup))
    assert( self.roleCanvasGroup )

    -- 设置 男/女 头像:
    local isMale = not CfUtils.IsWoman()
    self.uiSwitchImage.Status = (isMale==true) and 2 or 1
    
    
end 



function MazeUI_EdgeRole:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end





-- =============================================================== Self -> ================================================================== -- 



function MazeUI_EdgeRole:ShowRole( isShow )
    local alpha = isShow==true and 1.0 or 0.0 
    if Mathf.Abs(self.roleCanvasGroup.alpha - alpha) > 0.001  then 
        self.roleCanvasGroup.alpha = alpha 
        self.roleCanvasGroup.interactable = isShow
        self.roleCanvasGroup.blocksRaycasts = isShow
    end 

    -- if self.roleCanvasGroup.enabled ~= isShow then 
    --     self.roleCanvasGroup.enabled = isShow
    -- end 
end








return MazeUI_EdgeRole
